using System;
using System.IO;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Soulmask console over the server's maintenance port (-EchoPort = the service's RCON port).
// The server binds that port to 127.0.0.1 only and asks no password, so this runs on the service's own
// host and always connects to loopback. Commands: help, save 1, shutdown <seconds>, lp, ...
// ("quit" only closes this connection; "shutdown <seconds>" saves and exits).
var result = "";
try
{
    var address = "127.0.0.1";
    var port = Globals.Variables.Parse<int>("Port");
    var command = (Globals.Variables.Parse<string>("Command") ?? "").Trim();

    using (var client = new System.Net.Sockets.TcpClient())
    {
        var connect = client.ConnectAsync(address, port);
        if (await Task.WhenAny(connect, Task.Delay(5000)) != connect)
            throw new Exception("Timed out connecting to " + address + ":" + port);
        await connect;

        var stream = client.GetStream();
        var buffer = new byte[16384];
        var output = new System.IO.MemoryStream();

        // Send at once: the server reads a new connection on its next tick and drops it when nothing has arrived yet.
        var payload = System.Text.Encoding.UTF8.GetBytes(command + "\r\n");
        await stream.WriteAsync(payload, 0, payload.Length);
        await stream.FlushAsync();

        // Read until the server has been quiet for 2 s (8 s at most).
        var hardEnd = DateTime.UtcNow.AddSeconds(8);
        var lastData = DateTime.UtcNow;
        while (DateTime.UtcNow < hardEnd && DateTime.UtcNow - lastData < TimeSpan.FromMilliseconds(2000))
        {
            if (stream.DataAvailable)
            {
                var n = stream.Read(buffer, 0, buffer.Length);
                if (n <= 0) break;
                output.Write(buffer, 0, n);
                lastData = DateTime.UtcNow;
            }
            else
            {
                if (client.Client.Poll(0, System.Net.Sockets.SelectMode.SelectRead) && client.Client.Available == 0) break; // closed
                await Task.Delay(50);
            }
        }

        // Drop telnet IAC negotiation sequences (0xFF cmd opt) before decoding.
        var raw = output.ToArray();
        var clean = new System.IO.MemoryStream();
        for (var i = 0; i < raw.Length; i++)
        {
            if (raw[i] == 0xFF && i + 1 < raw.Length)
            {
                var cmd = raw[i + 1];
                if (cmd == 0xFF) { clean.WriteByte(0xFF); i++; }
                else if (cmd >= 0xFB && cmd <= 0xFE) i += 2;
                else i++;
                continue;
            }
            clean.WriteByte(raw[i]);
        }
        result = System.Text.Encoding.UTF8.GetString(clean.ToArray()).Replace("\r\n", "\n").Trim();
    }
}
catch (Exception ex)
{
    result = "Soulmask console error: " + ex.Message;
}
Globals.ReturnValue = result;

