using System;
using System.Diagnostics;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Graceful stop for Soulmask: send "shutdown 1" to the maintenance port (-EchoPort = the service's RCON
// port, bound to 127.0.0.1), which saves the world and exits, then wait until the process is gone so the
// panel's stop doesn't kill it mid-save. A big world can take minutes to write, hence the long wait.
var pid = ThisService.ProcessId;
var port = ThisService.RconPort;
const int maxWaitSeconds = 600;

bool IsRunning(int id)
{
    try { using (var p = Process.GetProcessById(id)) return !p.HasExited; }
    catch (ArgumentException) { return false; }
    catch (InvalidOperationException) { return false; }
}

if (pid == null || pid <= 0 || !IsRunning(pid.Value))
{
    ScriptConsole.WriteLine((object)"The server is not running; nothing to save.");
    return;
}

try
{
    using (var client = new TcpClient())
    {
        var connect = client.ConnectAsync("127.0.0.1", port);
        if (await Task.WhenAny(connect, Task.Delay(5000)) != connect)
            throw new Exception("timed out connecting to 127.0.0.1:" + port);
        await connect;
        var stream = client.GetStream();
        // Send at once: the server reads a new connection on its next tick and drops it when nothing has arrived yet.
        var payload = Encoding.UTF8.GetBytes("shutdown 1\r\n");
        await stream.WriteAsync(payload, 0, payload.Length);
        await stream.FlushAsync();
        var buffer = new byte[4096];
        var end = DateTime.UtcNow.AddSeconds(5);
        var reply = "";
        while (DateTime.UtcNow < end && reply.Length == 0)
        {
            if (stream.DataAvailable) reply = Encoding.UTF8.GetString(buffer, 0, stream.Read(buffer, 0, buffer.Length)).Trim();
            else await Task.Delay(100);
        }
        ScriptConsole.WriteLine((object)("shutdown 1: " + (reply.Length > 0 ? reply : "(no reply)")));
    }
}
catch (Exception ex)
{
    // Still loading, or the port is not open: the panel's own stop takes over.
    ScriptConsole.WriteLine((object)("Could not send the shutdown command (" + ex.Message + "); the server is stopped without saving."));
    return;
}

for (var second = 1; second <= maxWaitSeconds; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (!IsRunning(pid.Value))
    {
        ScriptConsole.WriteLine((object)("The world was saved and the server exited after " + second + " s."));
        return;
    }
}
ScriptConsole.WriteLine((object)("The server did not exit within " + maxWaitSeconds + " s; the panel stops it now."));

//refAssemblies: TCAdmin.Web.Shared.dll
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using TCAdmin.Web.Shared.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Soulmask loads the Workshop items listed in -mod="id1,id2" (the Mods variable). Add this item to the
// list and re-derive the command line; the server picks it up the next time it starts.
string fileId = Convert.ToString(Dynamic.FileId).Trim();

var service = await GameServiceManager.GetAsync(ThisService.ServiceId);
var current = service.Variables ?? new TCAdminVars();
var mods = current.Parse<string>("Mods", string.Empty)
    .Split(new[] { ',', ';', ' ' }, StringSplitOptions.RemoveEmptyEntries)
    .Select(x => x.Trim()).Where(x => x.Length > 0).ToList();

if (mods.Contains(fileId)) ScriptConsole.WriteLine((object)$"Workshop item {fileId} is already in the mod list.");
else mods.Add(fileId);

// Mods has "Sync value with all commandlines" on: this writes the list into every saved command line (a saved
// predefined or custom line keeps its own copy of the variables) and the service variable, then refreshes the
// active command line.
string value = string.Join(",", mods);
await ServiceManager.SyncCommandlineVariables(ThisService.Owner, ThisService, new TCAdminVars { ["Mods"] = value });
ScriptConsole.WriteLine((object)("Mods=" + value));
ScriptConsole.WriteLine((object)"Command line updated.");
ScriptConsole.WriteLine((object)"The mod is loaded the next time the server starts.");

