using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using TCAdmin.Web.Shared.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Soulmask loads the Workshop items listed in -mod="id1,id2" (the Mods variable). Remove this item from
// the list and re-derive the command line; the change applies the next time the server starts.
// The server also keeps its own copies: it downloads listed items into WS/Binaries/<platform>/steamapps
// and installs each plugin folder into WS/Mods. Those are removed too so nothing stale is left behind.
string fileId = Convert.ToString(Dynamic.FileId).Trim();

var service = await GameServiceManager.GetAsync(ThisService.ServiceId);
var current = service.Variables ?? new TCAdminVars();
var mods = current.Parse<string>("Mods", string.Empty)
    .Split(new[] { ',', ';', ' ' }, StringSplitOptions.RemoveEmptyEntries)
    .Select(x => x.Trim()).Where(x => x.Length > 0).ToList();

if (!mods.Remove(fileId)) ScriptConsole.WriteLine((object)$"Workshop item {fileId} is not in the mod list.");

// Mods has "Sync value with all commandlines" on: this writes the list into every saved command line (a saved
// predefined or custom line keeps its own copy of the variables) and the service variable, then refreshes the
// active command line.
string value = string.Join(",", mods);
await ServiceManager.SyncCommandlineVariables(ThisService.Owner, ThisService, new TCAdminVars { ["Mods"] = value });
ScriptConsole.WriteLine((object)("Mods=" + value));

// Each installed plugin folder carries ModeInfo.json (UTF-16) with the Workshop id as "ModID".
string root = ThisService.RootDirectory;
string modsRoot = Path.Combine(root, "WS", "Mods");
if (Directory.Exists(modsRoot))
{
    foreach (var dir in Directory.GetDirectories(modsRoot))
    {
        string info = Path.Combine(dir, "ModeInfo.json");
        if (!File.Exists(info)) continue;
        var match = System.Text.RegularExpressions.Regex.Match(File.ReadAllText(info), @"""ModID""\s*:\s*""?(\d+)");
        if (!match.Success || match.Groups[1].Value != fileId) continue;
        string name = Path.GetFileName(dir);
        try { Directory.Delete(dir, true); ScriptConsole.WriteLine((object)("Removed WS/Mods/" + name)); }
        catch (Exception ex) { ScriptConsole.WriteLine((object)("Could not remove WS/Mods/" + name + " (" + ex.Message + "). Stop the server and delete it.")); }
    }
}
foreach (var platform in new[] { "Win64", "Linux" })
{
    string serverCopy = Path.Combine(root, "WS", "Binaries", platform, "steamapps", "workshop", "content", "2646460", fileId);
    try { if (Directory.Exists(serverCopy)) { Directory.Delete(serverCopy, true); ScriptConsole.WriteLine((object)("Removed the server's download of " + fileId)); } }
    catch (Exception ex) { ScriptConsole.WriteLine((object)("Could not remove the server's download of " + fileId + " (" + ex.Message + ").")); }
}

ScriptConsole.WriteLine((object)"Command line updated.");
ScriptConsole.WriteLine((object)"The mod is no longer loaded from the next server start.");
